import{units,parseMeasure,fraction,format,boardFeet}from './math.js';
const $=id=>document.getElementById(id);let unit='in',pending=null,replace=false,roundingSource=null;
const names={in:'Inches',ft:'Feet',mm:'Millimetres',cm:'Centimetres',m:'Metres'};
const HISTORY_KEY='woodshop-calculation-history-v1';
let history=[];
try{const saved=JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]');if(Array.isArray(saved))history=saved.filter(item=>item&&['kind','expression','result','detail','time'].every(k=>typeof item[k]==='string')).slice(0,50);}catch{}
function showHistory(){
 $('history-list').replaceChildren();$('history-empty').hidden=history.length>0;$('clear-history').disabled=history.length===0;
 for(const item of history){const li=document.createElement('li');const meta=document.createElement('div');meta.className='history-meta';const date=new Date(item.time);meta.textContent=item.kind+(Number.isNaN(date.getTime())?'':' · '+date.toLocaleString());const calculation=document.createElement('div');calculation.className='history-calculation';calculation.textContent=item.expression+' = '+item.result;li.append(meta,calculation);if(item.detail){const detail=document.createElement('p');detail.textContent=item.detail;li.append(detail);}$('history-list').append(li);}
}
function saveHistory(){try{localStorage.setItem(HISTORY_KEY,JSON.stringify(history));}catch{$('history-storage').textContent='History is available for this session only; browser storage is unavailable.';}showHistory();}
function recordHistory(kind,expression,result,detail=''){history.unshift({kind,expression,result,detail,time:new Date().toISOString()});history=history.slice(0,50);saveHistory();}
$('clear-history').onclick=()=>{history=[];saveHistory();};showHistory();
function render(){try{const v=parseMeasure($('measurement').value)*units[unit];const precision=Number($('precision').value);$('error').textContent='';const rounded=parseMeasure(fraction(v,precision));const delta=rounded-(roundingSource??v);const tolerance=Number.EPSILON*Math.max(1,Math.abs(roundingSource??v))*4;const magnitude=n=>Math.abs(n)<0.000001?Math.abs(n).toExponential(3):format(Math.abs(n));$('rounding-error').textContent=Math.abs(delta)<=tolerance?'Rounding error: 0 in (0 mm) — exact.':`Rounding error: ${delta>0?'+':'−'}${magnitude(delta)} in (${delta>0?'+':'−'}${magnitude(delta*25.4)} mm) — rounded ${delta>0?'up':'down'} to 1/${precision}″.`;$('fraction-output').innerHTML=`${fraction(v,precision)}<span>″</span>`;$('rounding-note').textContent=`${Math.abs(v-Math.round(v*precision)/precision)<1e-9?'Exact at':'Rounded to nearest'} 1/${precision}″${pending?' · '+pending.operator+' pending':''}`;$('conversions').innerHTML=['in','ft','mm','cm','m'].map(u=>`<div class="result-row"><span>${u==='in'?'Decimal inches':names[u]}</span><strong>${format(v/units[u])} <small>${u}</small></strong></div>`).join('');return v;}catch(e){$('rounding-error').textContent='';$('error').textContent=e.message;$('fraction-output').textContent='—';$('rounding-note').textContent='Check your measurement';$('conversions').innerHTML='';return null;}}
function selectUnit(target){
 const before=$('measurement').value+' '+unit;const previousUnit=unit;
 const fractional=target==='fractions';const next=fractional?'in':target;
 try{const converted=parseMeasure($('measurement').value)*units[unit]/units[next];
 const text=fractional?fraction(converted,Number($('precision').value)):converted.toLocaleString('en-US',{useGrouping:false,maximumSignificantDigits:15});
 parseMeasure(text);if(fractional&&roundingSource===null)roundingSource=converted;$('measurement').value=text;
 }catch(e){$('error').textContent=e.message;return;}
 unit=next;$('screen-unit').textContent=next;
 document.querySelectorAll('[data-unit]').forEach(el=>{el.classList.toggle('active',el.dataset.unit===target);el.setAttribute('aria-pressed',String(el.dataset.unit===target));});render();
 if(fractional||previousUnit!==next)recordHistory(fractional?'Fraction rounding':'Conversion',before,$('measurement').value+' '+next,fractional?$('rounding-error').textContent:'');
}
for(const u of ['in','ft','fractions','cm','m']){const b=document.createElement('button');b.textContent=u==='fractions'?'Fractions':u;b.dataset.unit=u;b.className=u===unit?'active':'';b.setAttribute('aria-pressed',String(u===unit));if(u==='fractions')b.title='Round to fractional inches using the selected precision';b.onclick=()=>selectUnit(u);document.querySelector('.unit-buttons').append(b);}

for(const d of[8,16,32,64,128]){const b=document.createElement('button');b.textContent='1/'+d;b.setAttribute('aria-label',`Add one ${d}th of current unit`);b.onclick=()=>{try{roundingSource=null;const n=(replace?0:parseMeasure($('measurement').value))+1/d;$('measurement').value=fraction(n,128);replace=false;render();}catch(e){$('error').textContent=e.message;}};document.querySelector('.fractions').append(b);}
const keys=['C','⌫','±','÷','7','8','9','×','4','5','6','−','1','2','3','+','0','.','/','='];
function key(k){roundingSource=null;const input=$('measurement');if(k==='C'){input.value='0';pending=null;replace=false;}else if(k==='⌫'){input.value=input.value.slice(0,-1)||'0';replace=false;}else if(k==='±'){input.value=input.value.startsWith('-')?input.value.slice(1):'-'+input.value;}else if(['+','−','×','÷','='].includes(k)){const current=render();if(current===null)return;if(pending&&!replace){const right=parseMeasure(input.value);let result;if(pending.operator==='+')result=pending.value+current;else if(pending.operator==='−')result=pending.value-current;else if(pending.operator==='×')result=pending.value*right;else {if(right===0){$('error').textContent='Cannot divide by zero.';return;}result=pending.value/right;}if(!Number.isFinite(result)||Math.abs(result/units[unit])>1e12){$('error').textContent='Result is too large.';return;}const expression=(pending.expression||format(pending.value)+' in')+' '+pending.operator+' '+input.value+(['×','÷'].includes(pending.operator)?'':' '+unit);input.value=String(Number((result/units[unit]).toPrecision(13)));recordHistory('Calculation',expression,input.value+' '+unit);pending=null;}if(k!=='=')pending={value:parseMeasure(input.value)*units[unit],operator:k,expression:input.value+' '+unit};replace=true;}else{if(replace){input.value='';replace=false;}if(input.value==='0'&&k!=='.'&&k!=='/')input.value='';input.value+=k;}render();}
for(const k of keys){const b=document.createElement('button');b.textContent=k;b.className=k==='='?'equals':['+','−','×','÷'].includes(k)?'operator':['C','⌫','±'].includes(k)?'utility':'';b.setAttribute('aria-label',({'C':'Clear','⌫':'Backspace','±':'Change sign','/':'Fraction slash','×':'Multiply by a number','÷':'Divide by a number'})[k]||k);b.onclick=()=>key(k);document.querySelector('.keypad').append(b);}
$('measurement').addEventListener('input',()=>{roundingSource=null;replace=false;render();});$('measurement').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();key('=');}});$('precision').onchange=()=>{if(roundingSource!==null){unit='in';$('measurement').value=roundingSource.toLocaleString('en-US',{useGrouping:false,maximumSignificantDigits:15});selectUnit('fractions');}else render();};
document.querySelectorAll('.tab').forEach(b=>{b.onclick=()=>{document.querySelectorAll('.tab').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-current',t===b?'page':'false');});document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==b.dataset.tab);};});
function calculateBoards(){try{const result=boardFeet(...['thickness','width','length','quantity'].map(id=>parseMeasure($(id).value)),$('board-unit').value==='metric');$('board-total').textContent=format(result.total);$('board-single').textContent=format(result.single)+' bd ft';$('board-cubic').textContent=format(result.cubic)+' ft³';$('board-error').textContent='';return result;}catch(e){$('board-error').textContent=e.message;for(const id of['board-total','board-single','board-cubic'])$(id).textContent='—';return null;}}
$('board-form').onsubmit=e=>{e.preventDefault();const result=calculateBoards();if(result){const metric=$('board-unit').value==='metric';const dimension=metric?'mm':'in';const lengthUnit=metric?'m':'ft';recordHistory('Board feet',`${$('thickness').value} ${dimension} × ${$('width').value} ${dimension} × ${$('length').value} ${lengthUnit} × ${$('quantity').value} boards`,format(result.total)+' bd ft',format(result.single)+' bd ft per board');}};$('board-unit').onchange=()=>{const metric=$('board-unit').value==='metric';for(const id of['thickness','width','length']){try{const factor=id==='length'?0.3048:25.4;$(id).value=String(Number((parseMeasure($(id).value)*(metric?factor:1/factor)).toPrecision(12)));}catch{}$(id+'-unit').textContent='('+(metric?(id==='length'?'m':'mm'):(id==='length'?'ft':'in'))+')';}calculateBoards();};
function chart(){const d=Number($('chart-step').value);$('chart-body').innerHTML=Array.from({length:d+1},(_,n)=>`<tr class="${n%(d/8)===0?'common':''}"><td>${fraction(n/d,d)}″</td><td>${format(n/d)}</td><td>${format(n/d*25.4)}</td></tr>`).join('');}$('chart-step').onchange=chart;
let installEvent;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});$('install').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null;}else $('install-help').hidden=!$('install-help').hidden;};
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'convert_measurement',description:'Set the visible measurement and return its conversions.',inputSchema:{type:'object',properties:{measurement:{type:'string'},unit:{type:'string',enum:Object.keys(units)}},required:['measurement','unit'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const v=parseMeasure(input.measurement);if(!Object.hasOwn(units,input.unit))throw Error('Unknown unit');roundingSource=null;unit=input.unit;$('measurement').value=String(input.measurement);pending=null;replace=false;selectUnit(input.unit);return{inches:v*units[unit],millimetres:v*units[unit]*25.4,fraction:fraction(v*units[unit],Number($('precision').value))};}})).catch(()=>{});}catch{}}
render();chart();
